//! Database seeder binary for module: livechat
//!
//! Generated by metaphor-schema. Do not edit manually.
//!
//! Run with: cargo run --bin livechat-seeder
//! Or via CLI: backbone seed run --module livechat
//!
//! This binary runs all registered seeders in order.

use anyhow::Result;
use sqlx::postgres::PgPoolOptions;
use std::env;

// Import seeders
use backbone_livechat::seeders::SeedChannelMemberSeeder;
use backbone_livechat::seeders::SeedChannelRuleSeeder;
use backbone_livechat::seeders::SeedChannelSeeder;
use backbone_livechat::seeders::SeedChatbotAnswerSeeder;
use backbone_livechat::seeders::SeedChatbotMessageSeeder;
use backbone_livechat::seeders::SeedChatbotScriptSeeder;
use backbone_livechat::seeders::SeedChatbotStepSeeder;
use backbone_livechat::seeders::SeedChatbotStepTriggerSeeder;
use backbone_livechat::seeders::SeedConversationTagSeeder;
use backbone_livechat::seeders::SeedExpertiseTagSeeder;
use backbone_livechat::seeders::SeedLivechatAuditLogSeeder;
use backbone_livechat::seeders::SeedMemberHistorySeeder;
use backbone_livechat::seeders::SeedOperatorExpertiseSeeder;
use backbone_livechat::seeders::SeedOperatorProfileSeeder;
use backbone_livechat::seeders::SeedRatingSeeder;
use backbone_livechat::seeders::SeedSessionSeeder;
use backbone_livechat::seeders::SeedSessionTagSeeder;
use backbone_livechat::seeders::Seeder;

#[tokio::main]
async fn main() -> Result<()> {
    let args: Vec<String> = env::args().collect();
    let force = args.iter().any(|a| a == "--force");
    let filter: Option<&str> = args
        .iter()
        .skip(1)
        .find(|a| !a.starts_with("-"))
        .map(|s| s.as_str());

    let database_url =
        env::var("DATABASE_URL").map_err(|e| anyhow::anyhow!("DATABASE_URL must be set: {e}"))?;

    println!("Connecting to database...");

    let pool = PgPoolOptions::new()
        .max_connections(5)
        .connect(&database_url)
        .await?;

    println!("Connected to database");
    println!();
    println!("Running seeders for module: livechat");
    println!();

    // Register seeders in order
    let mut seeders: Vec<Box<dyn Seeder + Send + Sync>> = Vec::new();
    seeders.push(Box::new(SeedChannelSeeder::new()));
    seeders.push(Box::new(SeedChannelMemberSeeder::new()));
    seeders.push(Box::new(SeedChannelRuleSeeder::new()));
    seeders.push(Box::new(SeedChatbotAnswerSeeder::new()));
    seeders.push(Box::new(SeedChatbotMessageSeeder::new()));
    seeders.push(Box::new(SeedChatbotScriptSeeder::new()));
    seeders.push(Box::new(SeedChatbotStepSeeder::new()));
    seeders.push(Box::new(SeedChatbotStepTriggerSeeder::new()));
    seeders.push(Box::new(SeedConversationTagSeeder::new()));
    seeders.push(Box::new(SeedExpertiseTagSeeder::new()));
    seeders.push(Box::new(SeedLivechatAuditLogSeeder::new()));
    seeders.push(Box::new(SeedMemberHistorySeeder::new()));
    seeders.push(Box::new(SeedOperatorExpertiseSeeder::new()));
    seeders.push(Box::new(SeedOperatorProfileSeeder::new()));
    seeders.push(Box::new(SeedRatingSeeder::new()));
    seeders.push(Box::new(SeedSessionSeeder::new()));
    seeders.push(Box::new(SeedSessionTagSeeder::new()));

    // Sort by order
    seeders.sort_by_key(|s| s.order());

    // Run seeders
    for seeder in &seeders {
        let name = seeder.name();

        // Apply filter if specified
        if let Some(f) = filter {
            if !name.contains(f) {
                continue;
            }
        }

        if force {
            println!("   Running {}...", name);
            seeder.run(&pool).await?;
            println!("   {} completed", name);
        } else {
            println!("   Checking {}...", name);
            if seeder.should_run(&pool).await? {
                println!("   Running {}...", name);
                seeder.run(&pool).await?;
                println!("   {} completed", name);
            } else {
                println!("   {} already applied, skipping", name);
            }
        }
    }

    println!();
    println!("All seeders completed successfully!");

    Ok(())
}
